-- Rhode Island had nothing at all.
--
-- Thirteen categories arrived outside the enum. Several were settled by
-- looking at the stop rather than the word: 'underground' is Fort Adams'
-- tunnels, so a fortification rather than a cave, and 'ghost-lore' is the
-- Palatine Graves, a shipwreck story attached to a burial ground.
--
-- Purgatory Chasm goes in as purgatory-chasm-middletown, because Sutton,
-- Massachusetts holds the plain slug. Two different chasms, both real, and
-- New England is small enough that this will keep happening.
--
-- 90 stops, every one with a source.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Grave of Mercy Brown', 'grave-of-mercy-brown', 'folklore', 41.58061, -71.5598, 'Exeter', 'RI', 'Mercy Brown became the center of Rhode Island''s best-known vampire panic after several members of her family died from tuberculosis in the late 1800s. In 1892, townspeople exhumed her body, removed and burned her heart and liver, and used the ashes in an attempted folk remedy for her sick brother. Her grave survives in Chestnut Hill Cemetery and remains one of New England''s most important vampire-lore sites.', 'limited', 'https://www.atlasobscura.com/places/grave-mercy-brown', null, 'America/New_York', now()),
  ('The Conjuring House', 'the-conjuring-house', 'haunted', 42.00926, -71.70916, 'Harrisville', 'RI', 'The Arnold Estate farmhouse became internationally famous through claims investigated by Ed and Lorraine Warren and later dramatized in The Conjuring. The property has changed ownership and is undergoing restoration; the current operator states that it is private and plans to resume tours after restoration is complete. Do not enter the property unless an authorized visit is announced.', 'private', 'https://www.conjuringhouseofficial.com/', 'https://www.conjuringhouseofficial.com/', 'America/New_York', now()),
  ('H.P. Lovecraft''s Grave', 'hp-lovecrafts-grave', 'weird-history', 41.854, -71.3811, 'Providence', 'RI', 'Horror writer H.P. Lovecraft is buried with his parents in Swan Point Cemetery beneath a modest stone bearing the phrase "I AM PROVIDENCE." Fans routinely leave notes, coins, drawings and other small tributes at the grave. Visit only during cemetery hours and follow cemetery rules.', 'limited', 'https://www.atlasobscura.com/places/hp-lovecrafts-grave', null, 'America/New_York', now()),
  ('H.P. Lovecraft House', 'hp-lovecraft-house', 'weird-history', 41.82856, -71.4052, 'Providence', 'RI', 'Lovecraft lived at 65 Prospect Street during the final years of his life, and the house appears in altered form in his story "The Haunter of the Dark." It is a private residence rather than a museum. OddWay visitors should view it only from the public sidewalk and should not disturb the occupants.', 'private', 'https://www.atlasobscura.com/places/hp-lovecraft-house', null, 'America/New_York', now()),
  ('Providence Athenaeum', 'providence-athenaeum', 'weird-history', 41.8258, -71.4063, 'Providence', 'RI', 'This 1838 independent library is closely tied to Edgar Allan Poe, who spent time here during his courtship of poet Sarah Helen Whitman, and it was later frequented by H.P. Lovecraft. Its narrow galleries, old collections and literary associations give the building an atmosphere that fits naturally into a Providence weird-fiction route.', 'open', 'https://www.atlasobscura.com/places/providence-athenaeum', 'https://providenceathenaeum.org/', 'America/New_York', now()),
  ('John Hay Library', 'john-hay-library', 'museums', 41.82592, -71.40458, 'Providence', 'RI', 'Brown University''s John Hay Library preserves major H.P. Lovecraft collections along with unusual rare books and artifacts. The library has also become known for books in Brown''s collections that were historically bound in human skin. Public access is possible during designated service hours, but identification and current visitor rules should be checked before arrival.', 'limited', 'https://www.atlasobscura.com/places/john-hay-library', 'https://library.brown.edu/hay/', 'America/New_York', now()),
  ('Roger Williams Root', 'roger-williams-root', 'weird-history', 41.82292, -71.40344, 'Providence', 'RI', 'When Roger Williams''s remains were exhumed in 1860, workers found an apple-tree root growing through the old grave in a shape interpreted as resembling a human body. The preserved "root that ate Roger Williams" belongs to the Rhode Island Historical Society and has been displayed at the John Brown House Museum. As of September 2026 the museum lists the root as temporarily off-view for exhibit maintenance, so check before visiting specifically for it.', 'limited', 'https://www.rihs.org/locations/the-john-brown-house-museum/', 'https://www.rihs.org/locations/the-john-brown-house-museum/', 'America/New_York', now()),
  ('Providence Biltmore — Graduate Providence', 'providence-biltmore-graduate-providence', 'haunted', 41.82432, -71.41328, 'Providence', 'RI', 'Opened in 1922, the former Providence Biltmore has accumulated decades of stories involving unexplained voices, apparitions and other alleged paranormal activity. Its history also includes Prohibition-era nightlife and a long list of prominent guests. The building remains an operating downtown hotel, now known as Graduate Providence.', 'open', 'https://www.atlasobscura.com/places/providence-biltmore-graduate', null, 'America/New_York', now()),
  ('Ladd Observatory', 'ladd-observatory', 'weird-history', 41.83901, -71.39911, 'Providence', 'RI', 'Brown University''s 1891 observatory preserves historic astronomical instruments beneath its rotating dome. Public observing nights are normally held on Tuesday evenings when weather permits and require a free reservation. The combination of Victorian science, astronomy and a hilltop dome makes it a strong nighttime OddWay stop.', 'limited', 'https://physics.brown.edu/about/ladd-observatory', 'https://physics.brown.edu/about/ladd-observatory', 'America/New_York', now()),
  ('Gun Totem', 'gun-totem', 'roadside-oddities', 41.82512, -71.40759, 'Providence', 'RI', 'Artist Boris Bally built this roughly 3,500-pound obelisk from more than 1,000 firearms surrendered during a gun buyback. The weapons were crushed and welded into a towering public sculpture outside Providence''s federal courthouse. From a distance it resembles a dark stone monument; up close the individual gun parts become visible.', 'open', 'https://www.atlasobscura.com/places/gun-totem', null, 'America/New_York', now()),
  ('Fleur-de-Lys Studio', 'fleur-de-lys-studio', 'roadside-oddities', 41.82771, -71.40862, 'Providence', 'RI', 'Built in 1885 for the Providence Art Club, this highly decorated half-timbered studio looks dramatically different from the surrounding Colonial-era buildings on Thomas Street. Carved figures, patterned panels and an asymmetrical façade give it the appearance of an illustrated storybook building dropped into College Hill.', 'roadside', 'https://www.atlasobscura.com/places/fleur-de-lys-studio', null, 'America/New_York', now()),
  ('Big Blue Bug', 'big-blue-bug', 'roadside-oddities', 41.80707, -71.40588, 'Providence', 'RI', 'A gigantic blue termite named Nibbles Woodaway has stared down at Interstate 95 traffic since 1980. The roughly 58-foot-long insect became so recognizable that it evolved from a pest-control advertisement into one of Rhode Island''s best-known roadside icons.', 'roadside', 'https://www.atlasobscura.com/places/big-blue-bug', 'https://www.bigbluebug.com/', 'America/New_York', now()),
  ('Crook Point Bascule Bridge', 'crook-point-bascule-bridge', 'weird-history', 41.82431, -71.38339, 'Providence', 'RI', 'The abandoned Crook Point railroad bridge has remained permanently raised over the Seekonk River since rail service ended in 1976. Its rusting draw span points sharply into the sky and has become one of Providence''s most recognizable pieces of industrial decay. View it from lawful public areas; the bridge itself is not an exploration site.', 'roadside', 'https://www.atlasobscura.com/places/crook-point-bascule-bridge', null, 'America/New_York', now()),
  ('Edna W. Lawrence Nature Lab', 'edna-w-lawrence-nature-lab', 'museums', 41.827, -71.40803, 'Providence', 'RI', 'RISD''s Nature Lab holds tens of thousands of natural-history specimens used for art and design study, including bones, shells, insects, preserved animals and other biological material. Dense cabinets of specimens make the collection feel somewhere between an art studio and an old cabinet of curiosities. Public access varies with RISD programming, so check ahead.', 'limited', 'https://naturelab.risd.edu/', 'https://naturelab.risd.edu/', 'America/New_York', now()),
  ('Weird Providence — Lovecraft Arts & Sciences', 'weird-providence-lovecraft-arts-sciences', 'haunted', 41.82382, -71.41015, 'Providence', 'RI', 'Located inside the historic Arcade, Weird Providence is the home of Lovecraft Arts & Sciences and specializes in weird fiction, cosmic horror, occult material and Providence''s H.P. Lovecraft legacy. The nonprofit also supports NecronomiCon Providence and maintains information about unusual sites around the city.', 'open', 'https://www.weirdprovidence.org/', 'https://www.weirdprovidence.org/', 'America/New_York', now()),
  ('Newport Tower', 'newport-tower', 'folklore', 41.48581, -71.30987, 'Newport', 'RI', 'The circular stone tower in Touro Park has inspired centuries of speculation about Vikings, medieval explorers and other pre-Columbian visitors to New England. Archaeological and historical evidence instead strongly connects it to a seventeenth-century windmill associated with Governor Benedict Arnold. The competing theories have made it one of Rhode Island''s longest-running historical mysteries.', 'open', 'https://www.atlasobscura.com/places/newport-tower', null, 'America/New_York', now()),
  ('White Horse Tavern', 'white-horse-tavern', 'haunted', 41.4914, -71.31379, 'Newport', 'RI', 'Operating in a building dating to the seventeenth century, the White Horse Tavern is among America''s oldest surviving taverns. The restaurant has accumulated ghost stories involving colonial-era figures and unexplained activity, although these claims remain folklore rather than verified events. It remains an active restaurant rather than a dedicated paranormal attraction.', 'open', 'https://www.atlasobscura.com/places/white-horse-tavern', 'https://whitehorsenewport.com/', 'America/New_York', now()),
  ('Belcourt of Newport', 'belcourt-of-newport', 'haunted', 41.45463, -71.30284, 'Newport', 'RI', 'Designed by Richard Morris Hunt and completed in 1894, Belcourt is one of Newport''s strangest Gilded Age mansions, combining French Gothic and Renaissance influences around enormous carriage spaces. Later owners promoted stories of haunted antiques and unexplained phenomena inside the house. Visits are through scheduled tours and events.', 'limited', 'https://www.atlasobscura.com/places/belcourt-castle', 'https://www.belcourt.com/', 'America/New_York', now()),
  ('Carey Mansion', 'carey-mansion', 'weird-history', 41.468, -71.30385, 'Newport', 'RI', 'This sprawling French Renaissance-style mansion became Collinwood, the exterior of the haunted family estate in the cult television series "Dark Shadows." The building is part of a private property and is not a casual walk-in attraction. View only from lawful public areas and do not enter the grounds without permission.', 'private', 'https://www.atlasobscura.com/places/carey-mansion', null, 'America/New_York', now()),
  ('Rose Island Lighthouse', 'rose-island-lighthouse', 'weird-history', 41.49549, -71.34271, 'Newport', 'RI', 'Built in 1870 on tiny Rose Island beneath the Newport Pell Bridge, this restored lighthouse can be reached by boat for tours and even overnight stays. The island also contains remnants of historic Fort Hamilton and protected wildlife habitat. Public access is seasonal and depends on transportation, weather and nesting restrictions.', 'limited', 'https://www.roseisland.org/daytrips', 'https://www.roseisland.org/', 'America/New_York', now()),
  ('Green Animals Topiary Garden', 'green-animals-topiary-garden', 'roadside-oddities', 41.6055, -71.2707, 'Portsmouth', 'RI', 'Dozens of shrubs have been clipped into oversized animals and geometric forms across this historic estate, including bears, birds, a camel and a giraffe. The collection dates back more than a century and is considered the oldest topiary garden in the United States. Admission and operating dates follow the Preservation Society''s seasonal schedule.', 'limited', 'https://www.atlasobscura.com/places/green-animals-topiary-garden', 'https://www.newportmansions.org/mansions-and-gardens/green-animals-topiary-garden/', 'America/New_York', now()),
  ('Modern Diner', 'modern-diner', 'roadside-oddities', 41.86883, -71.38688, 'Pawtucket', 'RI', 'This streamlined stainless-steel diner is a surviving 1940 Sterling Streamliner and became the first diner placed on the National Register of Historic Places. Its rounded, locomotive-like exterior looks more like a retro-futurist railcar than a conventional restaurant. It remains open for breakfast and lunch.', 'open', 'https://www.atlasobscura.com/places/modern-diner', 'https://moderndinerri.com/', 'America/New_York', now()),
  ('The Fantastic Umbrella Factory', 'the-fantastic-umbrella-factory', 'roadside-oddities', 41.37749, -71.6617, 'Charlestown', 'RI', 'Despite the name, this rambling rural attraction is not an umbrella factory. The property grew into a collection of small shops, gardens, wandering animals, sculptures and quirky structures spread through a wooded setting. It has the loose, handmade character of an old-school roadside attraction rather than a conventional shopping center.', 'open', 'https://www.atlasobscura.com/places/the-fantastic-umbrella-factory', 'https://www.fantasticumbrellafactory.com/', 'America/New_York', now()),
  ('Nine Men''s Misery', 'nine-mens-misery', 'weird-history', 41.93982, -71.40662, 'Cumberland', 'RI', 'A stone monument in the woods marks the place where nine colonial soldiers were killed during King Philip''s War in 1676. Their remains were later excavated and reburied more than once before eventually being returned to the site. The memorial is reached by trail inside the Monastery property.', 'open', 'https://www.atlasobscura.com/places/nine-mens-misery', null, 'America/New_York', now()),
  ('Cumberlandite at Iron Mine Hill', 'cumberlandite-at-iron-mine-hill', 'roadside-oddities', 42.00399, -71.45663, 'Cumberland', 'RI', 'Iron Mine Hill contains one of the best-known exposures of Cumberlandite, an unusually dense magnetic rock found in significant quantities almost nowhere outside this part of Rhode Island. The material was named the official state rock in 1966. Reaching the outcrops involves a real hike, so visitors should use established trails and leave the rock in place.', 'open', 'https://www.oceanstatemedia.org/climate-environment/2026-07-15/rhode-island-rocks-our-quest-for-cumberlandite', null, 'America/New_York', now()),
  ('Memorial to Betty the Learned Elephant', 'memorial-to-betty-the-learned-elephant', 'weird-history', 41.9138, -71.67011, 'Chepachet', 'RI', 'A small memorial recalls Betty, an elephant traveling with a nineteenth-century menagerie who was shot and killed in Chepachet in 1826. Accounts say a local man fired after becoming angry when the elephant would not respond to him. The understated roadside marker preserves one of Rhode Island''s strangest and saddest animal stories.', 'roadside', 'https://www.atlasobscura.com/places/memorial-to-betty-the-learned-elephant', null, 'America/New_York', now()),
  ('New England Wireless and Steam Museum', 'new-england-wireless-and-steam-museum', 'museums', 41.62427, -71.51302, 'East Greenwich', 'RI', 'This specialized museum preserves early radio equipment, wireless technology and working steam engines in several historic buildings. Its collections connect the development of communications with the machinery that powered nineteenth-century industry. Public openings and demonstrations are scheduled rather than daily, so check the museum calendar before routing here.', 'limited', 'https://newsm.org/', 'https://newsm.org/', 'America/New_York', now()),
  ('Jerimoth Hill', 'jerimoth-hill', 'roadside-oddities', 41.84942, -71.77887, 'Foster', 'RI', 'At 812 feet, Jerimoth Hill is Rhode Island''s highest natural point. It was once notorious among highpointers because access crossed private land whose former owner sharply restricted visitors, but the approach is now publicly accessible. The summit itself is subtle rather than dramatic, making the historical difficulty of reaching it part of the oddity.', 'open', 'https://www.atlasobscura.com/places/jerimoth-hill', null, 'America/New_York', now()),
  ('Spring Lake Arcade', 'spring-lake-arcade', 'museums', 41.98668, -71.65689, 'Glendale', 'RI', 'Inside Spring Lake Beach is a remarkable collection of vintage coin-operated amusement machines, including mechanical games dating back generations. The arcade is often described as one of the country''s oldest penny arcades still in operation. It follows the seasonal schedule of the town beach, so verify the current season before traveling.', 'limited', 'https://www.burrillville.org/business-directory/spring-lake-arcade', 'https://www.burrillville.org/parks-recreation/pages/spring-lake-beach', 'America/New_York', now()),
  ('Rhode Island Red Monument', 'rhode-island-red-monument', 'roadside-oddities', 41.55359, -71.12889, 'Adamsville', 'RI', 'A granite monument in the village of Adamsville commemorates the Rhode Island Red, the chicken breed developed in this area during the nineteenth century. The bird later became Rhode Island''s official state bird. The monument turns an otherwise ordinary roadside corner into a shrine to poultry history.', 'roadside', 'https://www.atlasobscura.com/places/rhode-island-red-monument', null, 'America/New_York', now()),
  ('James DeWolf Burial Mound', 'james-dewolf-burial-mound', 'weird-history', 41.66495, -71.25859, 'Bristol', 'RI', 'A large earthen burial mound in Juniper Hill Cemetery contains the remains of James DeWolf, a U.S. senator who became enormously wealthy through the transatlantic slave trade. The unusual family tomb was later broken into, with stories that thieves sought valuables and even gold dental work. Visit respectfully during cemetery hours.', 'limited', 'https://www.roadsideamerica.com/tip/37927', null, 'America/New_York', now()),
  ('Sarah Swan Tombstone — Original Stone', 'sarah-swan-tombstone-original-stone', 'weird-history', 41.66956, -71.27508, 'Bristol', 'RI', 'The original eighteenth-century gravestone of Sarah Swan became a local curiosity because its carved portrait appears unusually expressive and distinctive compared with standard New England funerary art. To protect it from weather and vandalism, the original stone was moved to the Bristol Historical & Preservation Society while a replica marks the grave. Check museum hours before visiting specifically for the original.', 'limited', 'https://www.atlasobscura.com/places/sarah-swan-tombstone', 'https://www.bhpsri.org/', 'America/New_York', now()),
  ('Carter Jackson Monument', 'carter-jackson-monument', 'weird-history', 41.44852, -71.47351, 'Wakefield', 'RI', 'Hidden in brush near Tower Hill Road, this tall granite monument is covered with an unusually long inscription recounting an eighteenth-century murder involving William Jackson and sea captain Thomas Carter. The monument was erected more than a century after the event by eccentric spiritualist Joseph Peace Hazard. It stands close to a busy roadway, so approach only from a safe lawful area.', 'roadside', 'https://www.hmdb.org/m.asp?m=228064', null, 'America/New_York', now()),
  ('Cow Vomit Rope — Little Compton Historical Society', 'cow-vomit-rope-little-compton-historical-society', 'museums', 41.49202, -71.18452, 'Little Compton', 'RI', 'Among Little Compton''s stranger preserved artifacts is a rope-like mass traditionally described as having been vomited up by a cow. The object has survived as part of the local historical collection precisely because generations found it too bizarre to discard. Museum access is seasonal, so confirm current hours before traveling.', 'limited', 'https://littlecompton.org/', 'https://littlecompton.org/', 'America/New_York', now()),
  ('1964 World''s Fair General Foods Arch', '1964-worlds-fair-general-foods-arch', 'roadside-oddities', 41.68775, -71.3683, 'Warwick', 'RI', 'A 60-foot parabolic arch from the 1964–65 New York World''s Fair now stands inside Rocky Point State Park. It was one of 11 General Foods "Archways to Understanding" that originally carried electronic information displays for fairgoers. After relocation to Rocky Point it became a familiar meeting landmark and survived the amusement park itself.', 'open', 'https://www.roadsideamerica.com/tip/56662', null, 'America/New_York', now()),
  ('Vampire Grasp Grave of Simon Whipple Aldrich', 'vampire-grasp-grave-of-simon-whipple-aldrich', 'folklore', 41.98806, -71.52972, 'North Smithfield', 'RI', 'Simon Whipple Aldrich''s 1841 gravestone contains the striking phrase "Consumption''s vampire grasp," referring poetically to tuberculosis rather than documenting an accusation that Aldrich was a vampire. The wording has nevertheless made the grave an unusual stop within New England''s broader vampire tradition. The stone is in the historic Union Cemetery Annex area; visit only during daylight and respect the graves. Secondary source: https://www.roadsideamerica.com/tip/43658', 'limited', 'https://rihistoriccemeteries.org/newgravedetails.aspx?ID=170741', null, 'America/New_York', now()),
  ('Fighting Seabee Statue', 'fighting-seabee-statue', 'roadside-oddities', 41.60647, -71.44985, 'North Kingstown', 'RI', 'A muscular bronze Seabee carrying a rifle and heavy tools stands outside the Seabee Museum and Memorial Park near the former Quonset Point naval base. The figure reproduces the famous "Fighting Seabee" image associated with the U.S. Naval Construction Battalions. Check museum and grounds hours before visiting.', 'limited', 'https://www.seabeesmuseum.com/', 'https://www.seabeesmuseum.com/', 'America/New_York', now()),
  ('The Feet and the Wave', 'the-feet-and-the-wave', 'roadside-oddities', 41.48413, -71.31491, 'Newport', 'RI', 'At the entrance to Newport''s Brick Market area, two giant bronze feet appear to step out of a curling wave embedded in the pavement. The surreal sculpture is easy to miss among the shops, but its disembodied scale makes it one of downtown Newport''s stranger pieces of public art.', 'open', 'https://www.roadsideamerica.com/tip/72753', null, 'America/New_York', now()),
  ('Hurdy Gurdy Man and Monkey', 'hurdy-gurdy-man-and-monkey', 'roadside-oddities', 41.48855, -71.3156, 'Newport', 'RI', 'A bronze street performer and his small monkey occupy a permanent spot in downtown Newport. The life-size pair look like buskers frozen in place and have become a whimsical photo stop amid the historic commercial district.', 'open', 'https://www.roadsideamerica.com/tip/21184', null, 'America/New_York', now()),
  ('Point Judith Lighthouse Cairns', 'point-judith-lighthouse-cairns', 'weird-history', 41.36139, -71.48108, 'Narragansett', 'RI', 'Visitors around Point Judith have built clusters of small stone cairns near the dramatic lighthouse and rocky shoreline. The area also looks over waters tied to the 1945 sinking of German submarine U-853 and other maritime losses, giving the scenic stop a darker historical layer. Stay within areas legally open to the public and respect Coast Guard restrictions around the lighthouse.', 'roadside', 'https://www.atlasobscura.com/places/point-judith-lighthouse-cairns', null, 'America/New_York', now()),
  ('Great Swamp Fight Monument', 'great-swamp-fight-monument', 'weird-history', 41.47307, -71.59642, 'South Kingstown', 'RI', 'A granite monument deep in the Great Swamp commemorates the December 1675 battle in which colonial forces attacked a fortified Narragansett settlement during King Philip''s War. Hundreds of Narragansett people, including noncombatants, were killed. The monument is reached by an undeveloped walk and should be treated as a historical memorial rather than a casual photo prop.', 'open', 'https://www.hmdb.org/m.asp?m=21276', null, 'America/New_York', now()),
  ('Station Fire Memorial Park', 'station-fire-memorial-park', 'weird-history', 41.6843, -71.5109, 'West Warwick', 'RI', 'This memorial occupies the site of The Station nightclub, where a pyrotechnic fire on February 20, 2003 killed 100 people and injured more than 200. The park was created by victims'' families, survivors and supporters as a permanent place of remembrance. This should be presented by OddWay as respectful dark history, not as a paranormal attraction.', 'open', 'https://www.stationfirememorialfoundation.org/', 'https://www.stationfirememorialfoundation.org/', 'America/New_York', now()),
  ('Southeast Lighthouse', 'southeast-lighthouse', 'weird-history', 41.1513, -71.5737, 'New Shoreham', 'RI', 'Block Island''s dramatic brick Southeast Lighthouse was completed in the 1870s near the Mohegan Bluffs. Coastal erosion eventually brought the cliffs dangerously close, forcing the entire lighthouse to be moved back from the edge in 1993. Tours and interior access are seasonal, while exterior access depends on current site conditions.', 'limited', 'https://www.atlasobscura.com/places/southeast-lighthouse', 'https://southeastlighthouse.org/', 'America/New_York', now()),
  ('Fort Wetherill', 'fort-wetherill', 'weird-history', 41.4801, -71.3618, 'Jamestown', 'RI', 'Concrete gun batteries from the former coastal-defense Fort Wetherill remain embedded in cliffs above Narragansett Bay. Many surfaces are covered with layers of graffiti, creating a striking collision of military ruins and constantly changing street art. The surrounding state park is public, but visitors should obey closures and never enter unsafe or restricted structures.', 'open', 'https://www.atlasobscura.com/places/fort-wetherill', 'https://riparks.ri.gov/parks/fort-wetherill-state-park', 'America/New_York', now()),
  ('Erik Rock — Rhode Island Troll Trail', 'erik-rock-rhode-island-troll-trail', 'roadside-oddities', 41.36747, -71.66166, 'Charlestown', 'RI', 'Erik Rock is one of five giant Rhode Island trolls built from reclaimed materials by Danish artist Thomas Dambo. Installed at Ninigret Park in 2024, Erik sits near Little Ninigret Pond and contains clues directing visitors toward companion troll Greta Granit. The sculpture is free to visit; climbing on the troll is discouraged.', 'open', 'https://www.southcountyri.com/thomas-dambo-trolls/', null, 'America/New_York', now()),
  ('Greta Granit — Rhode Island Troll Trail', 'greta-granit-rhode-island-troll-trail', 'roadside-oddities', 41.37199, -71.66117, 'Charlestown', 'RI', 'Greta Granit crouches in the woods of Ninigret Park at the end of a marked search from fellow troll Erik Rock. Built with community volunteers and recycled wood, she is distinguished by a long bamboo ponytail. Greta and Erik are separate permanent installations and each functions as its own routable stop.', 'open', 'https://www.southcountyri.com/thomas-dambo-trolls/', null, 'America/New_York', now()),
  ('Iver Mudslider — Rhode Island Troll Trail', 'iver-mudslider-rhode-island-troll-trail', 'roadside-oddities', 41.56955, -71.48851, 'North Kingstown', 'RI', 'Iver Mudslider joined Rhode Island''s Thomas Dambo Troll Trail in 2025 and hides along a short walk in Ryan Park. Like Dambo''s other giant trolls, Iver is constructed largely from discarded and reclaimed wood and is intended to draw visitors into the landscape rather than simply sit beside a road.', 'open', 'https://www.southcountyri.com/thomas-dambo-trolls/', null, 'America/New_York', now()),
  ('Young Boulder — Rhode Island Troll Trail', 'young-boulder-rhode-island-troll-trail', 'roadside-oddities', 41.5592, -71.68773, 'Richmond', 'RI', 'Young Boulder is a giant recycled-wood troll hidden near Browning Mill Pond in the Arcadia Management Area. Added in 2025, the sculpture requires a woodland walk and turns the search itself into part of the attraction. Follow current trail rules and do not climb on the sculpture.', 'open', 'https://www.southcountyri.com/thomas-dambo-trolls/', null, 'America/New_York', now()),
  ('Mrs. Skipper — Rhode Island Troll Trail', 'mrs-skipper-rhode-island-troll-trail', 'roadside-oddities', 41.79588, -71.37996, 'East Providence', 'RI', 'Mrs. Skipper is the easternmost member of Rhode Island''s five-troll Thomas Dambo trail and sits near Kettle Point in East Providence. The oversized figure was completed in 2025 from reclaimed materials and expanded the project beyond South County. It is free to visit and intended as an interactive outdoor artwork rather than a climbing structure.', 'open', 'https://www.southcountyri.com/thomas-dambo-trolls/', null, 'America/New_York', now()),
  ('Nori the Dragon', 'nori-the-dragon', 'roadside-oddities', 41.81651, -71.40939, 'Providence', 'RI', 'A gigantic green dragon appears to crawl over the roof of the Providence Children''s Museum, with its head and tail visible on opposite sides of the building. The sculpture survived an earlier home before being adopted by the museum and later received the name Nori through a children''s contest. Museum admission is required for the full visit, though portions of the dragon can be seen from outside.', 'limited', 'https://www.atlasobscura.com/places/nori-the-dragon', 'https://providencechildrensmuseum.org/', 'America/New_York', now()),
  ('Fort Adams Underground Tunnels', 'fort-adams-underground-tunnels', 'weird-history', 41.47847, -71.33818, 'Newport', 'RI', 'Fort Adams contains an extensive network of listening tunnels built beneath one of America''s largest coastal fortifications. Guided tours descend into the passageways and explain how soldiers used them to detect enemy attempts to tunnel beneath the walls. Tunnel access follows the fort''s operating season and tour schedule.', 'limited', 'https://fortadams.org/visit-fort-adams/', 'https://fortadams.org/', 'America/New_York', now()),
  ('Barnaby Castle', 'barnaby-castle', 'weird-history', 41.81754, -71.4302, 'Providence', 'RI', 'This extravagant 1875 Victorian mansion became connected to one of the country''s earliest nationally famous murder-by-mail cases after widow Josephine Barnaby was poisoned with whiskey in 1891. The castle-like house has also accumulated reports of cold spots, uneasy sensations and other alleged paranormal activity. It is private property outside select tours and events, so exterior viewing should remain on the public sidewalk. Secondary source: https://sah-archipedia.org/buildings/RI-01-PR186', 'limited', 'https://hauntbound.com/locations/ri/barnaby-castle-providence/', null, 'America/New_York', now()),
  ('Hearthside House Museum', 'hearthside-house-museum', 'haunted', 41.90675, -71.43014, 'Lincoln', 'RI', 'Built around 1810, Hearthside is a preserved Federal-style mansion filled with period rooms, historic objects and local stories. The house has also developed a reputation for reported footsteps, apparitions and unexplained activity during its long history. Access is through scheduled museum openings, tours and events.', 'limited', 'https://greatroadheritagecampus.org/', 'https://greatroadheritagecampus.org/', 'America/New_York', now()),
  ('Annmary Brown Memorial', 'annmary-brown-memorial', 'weird-history', 41.82431, -71.40222, 'Providence', 'RI', 'Brown University''s stone Annmary Brown Memorial was built in the early twentieth century as a library, art gallery and mausoleum. Rush Hawkins and his wife Annmary Brown are entombed inside, surrounded by a collection assembled by Hawkins. Public hours can be limited or suspended, so current access should be checked before routing here.', 'limited', 'https://lib.brown.edu/using-library/visiting-library/locations-hours/annmary-brown-memorial', null, 'America/New_York', now()),
  ('Sarah Tillinghast Family Cemetery', 'sarah-tillinghast-family-cemetery', 'folklore', 41.58133, -71.60419, 'Exeter', 'RI', 'Local tradition connects this small family cemetery with Sarah Tillinghast, whose father reportedly became convinced that she was returning from the grave while tuberculosis spread through the family. The story became one of Rhode Island''s lesser-known vampire legends, although the surviving historical record is less certain than the Mercy Brown case. The cemetery is a sensitive historic burial ground and should be visited respectfully in daylight. Secondary source: https://www.atlasobscura.com/places/grave-mercy-brown', 'limited', 'https://locationsoflore.com/2018/07/26/the-vampire-case-of-sarah-tillinghast/', null, 'America/New_York', now()),
  ('Plain Meeting House Cemetery — Nellie Vaughn Legend', 'plain-meeting-house-cemetery-nellie-vaughn-legend', 'haunted', 41.63806, -71.75278, 'West Greenwich', 'RI', 'Nellie Vaughn died in 1889, but her grave later became surrounded by stories describing her as a witch, vampire or restless ghost. Investigations of the legend show that many of the supernatural claims appeared long after her death, making the site as much a lesson in how folklore evolves as a haunted stop. Her original marker is no longer present, so the cemetery itself is the route point. Secondary source: https://ournewenglandlegends.com/podcast-251-nellie-vaughn-vampire-witch-ghost/', 'limited', 'https://www.pbs.org/video/8-nelly-vaughn-gb2odo/', null, 'America/New_York', now()),
  ('Devil''s Foot Rock', 'devils-foot-rock', 'folklore', 41.60245, -71.4557, 'North Kingstown', 'RI', 'Three unusual impressions in this roadside rock have long been explained through local folklore as footprints left by the Devil. Versions of the story vary, but the marks turned an otherwise ordinary boulder into a persistent Rhode Island legend. View from a safe lawful roadside area and do not enter neighboring private property.', 'roadside', 'https://basementofthebizarre.com/2021/03/02/roadside-rhode-island-devils-foot-rock-north-kingstown-rhode-island/', null, 'America/New_York', now()),
  ('Palatine Graves', 'palatine-graves', 'haunted', 41.15519, -71.60266, 'New Shoreham', 'RI', 'This historic Block Island cemetery is traditionally associated with survivors and victims connected to the 1738 wreck of the Princess Augusta, remembered in folklore as the Palatine. The disaster later inspired stories of the Palatine Light, a flaming ghost ship said to appear offshore around the anniversary season. Historians dispute darker versions of the legend, but the cemetery remains a concrete location tied to the story. Secondary source: https://www.pbs.org/video/2-princess-augusta-jq5wjr/', 'limited', 'https://www.newshorehamri.gov/292/Cemetery', null, 'America/New_York', now()),
  ('Painted Rock', 'painted-rock', 'roadside-oddities', 41.15702, -71.58608, 'New Shoreham', 'RI', 'Since 1962, residents and visitors have repeatedly repainted this boulder at the junction of Mohegan Trail, Lakeside Drive and Snake Hole Road. Designs can change within days during the summer, leaving countless older layers sealed underneath the newest message. It is one of Block Island''s most enduring handmade roadside traditions. Secondary source: https://torijonesstudio.com/pages/visit-us-on-block-island', 'open', 'https://www.blockislandinfo.com/plan-your-visit/maps/bike-tour-map/', null, 'America/New_York', now()),
  ('Musée Patamécanique', 'mus-e-patam-canique', 'museums', 41.67711, -71.2662, 'Bristol', 'RI', 'Musée Patamécanique is an intentionally strange cabinet of curiosities inspired by pataphysics, automata and absurdist invention. Its objects and installations blur the line between museum, mechanical theater and conceptual art. Access has historically been appointment-based and irregular, so availability should be confirmed before routing a trip around it.', 'limited', 'https://www.atlasobscura.com/places/musee-patamecanique', null, 'America/New_York', now()),
  ('Peggotty at the Wilbor House', 'peggotty-at-the-wilbor-house', 'roadside-oddities', 41.49528, -71.18639, 'Little Compton', 'RI', 'Peggotty is an eccentric thatched artist''s studio designed to resemble an overturned boat and built by Rhode Island artist Sydney Burleigh in the early 1900s. The unusual structure was preserved and relocated to the Little Compton Historical Society''s Wilbor House property. Museum access is seasonal.', 'limited', 'https://littlecompton.org/', 'https://littlecompton.org/', 'America/New_York', now()),
  ('Spite Tower', 'spite-tower', 'folklore', 41.55383, -71.12765, 'Adamsville', 'RI', 'Local legend claims this three-story tower was deliberately built to block a neighbor''s view after a feud, earning it the name Spite Tower. Historical research indicates the much less dramatic truth: it was constructed around 1905 as a water tower supplying gravity-fed plumbing to the adjacent estate. The structure is private property but visible from the public road. Secondary source: https://www.roadsideamerica.com/tip/77134', 'roadside', 'https://www.rimonthly.com/spite-tower-in-little-compton/', null, 'America/New_York', now()),
  ('Druid''s Chair and Stone Circle', 'druids-chair-and-stone-circle', 'folklore', 41.42639, -71.46868, 'Narragansett', 'RI', 'Near Gibson Avenue Cemetery is a collection of stone features known as the Druid''s Chair, stone circle and, in some accounts, the "witches'' altar." Rhode Island cemetery records attribute the unusual landscaping to eccentric spiritualist Joseph Peace Hazard in the late nineteenth century rather than an ancient ritual site. The area can be overgrown and should be approached only through lawful cemetery access. Secondary source: https://www.roadsideamerica.com/tip/38961', 'limited', 'https://rihistoriccemeteries.org/newsearchcemeterydetail.aspx?ceme_no=NG003', null, 'America/New_York', now()),
  ('Enishkeetompauog Narragansett — Whispering Giant', 'enishkeetompauog-narragansett-whispering-giant', 'roadside-oddities', 41.43363, -71.46615, 'Narragansett', 'RI', 'This approximately 20-foot wooden figure was carved by artist Peter Toth as part of his nationwide Whispering Giants series honoring Indigenous peoples. Installed in 1982, the sculpture is known as Enishkeetompauog Narragansett and stands in Sprague Park. Weathering has made the towering face even more striking over time.', 'open', 'https://www.southcountyri.com/blog/post/peter-toth-and-the-narragansett-whispering-giant/', 'https://www.narragansettri.gov/Facilities/Facility/Details/Sprague-Park-16', 'America/New_York', now()),
  ('Narragansett Rune Stone', 'narragansett-rune-stone', 'folklore', 41.57006, -71.45256, 'North Kingstown', 'RI', 'This large inscribed boulder generated theories involving Vikings, Norse explorers and even the Knights Templar after its markings became widely known in the twentieth century. Its true origin remains unresolved, and the state recovered the stone after it was removed from Narragansett Bay in 2012. It is now displayed publicly in Wickford at 55 Brown Street. Secondary source: https://www.ri.gov/press/view/19214', 'open', 'https://www.visitrhodeisland.com/listing/narragansett-rune-stone/7979/', null, 'America/New_York', now()),
  ('Grave of George Mendonsa — The Kissing Sailor', 'grave-of-george-mendonsa-the-kissing-sailor', 'weird-history', 41.54266, -71.30541, 'Middletown', 'RI', 'George Mendonsa, widely identified as the sailor in Alfred Eisenstaedt''s famous V-J Day Times Square photograph, is buried in St. Columba Cemetery. His grave marker reproduces the instantly recognizable embrace in etched stone. The coordinate routes to the cemetery; visitors should follow cemetery rules and locate the individual grave respectfully.', 'limited', 'https://www.roadsideamerica.com/tip/70203', null, 'America/New_York', now()),
  ('Bruce the Shark at Flo''s Clam Shack', 'bruce-the-shark-at-flos-clam-shack', 'roadside-oddities', 41.48991, -71.28474, 'Middletown', 'RI', 'A roughly 25-foot shark hangs above Flo''s Clam Shack, looking like a creature that landed on the building rather than a restaurant decoration. The fiberglass-and-foam shark previously belonged to a Cranston nightclub before being rescued and relocated to Aquidneck Island. It is visible from the restaurant exterior.', 'open', 'https://admiralsimsnewport.com/off-the-beaten-path-newport-ri/', 'https://flosclamshacks.com/locations/', 'America/New_York', now()),
  ('JFK Rejected Grave Slab', 'jfk-rejected-grave-slab', 'weird-history', 41.48908, -71.31463, 'Newport', 'RI', 'Outside the Boys & Girls Club sits a granite prototype created during development of President John F. Kennedy''s grave memorial. Newport stonecarver John E. Benson produced the slab using words from Kennedy''s inaugural address, but the design was not used at Arlington National Cemetery. The discarded prototype survives as an unexpectedly important artifact in an ordinary city setting. Secondary source: https://admiralsimsnewport.com/off-the-beaten-path-newport-ri/', 'open', 'https://www.roadsideamerica.com/story/46290', null, 'America/New_York', now()),
  ('Location of the First Gas Street Lamp', 'location-of-the-first-gas-street-lamp', 'weird-history', 41.48615, -71.31471, 'Newport', 'RI', 'A memorial lamp and plaque mark the site where inventor David Melville demonstrated an early gas streetlight in Newport during the first years of the nineteenth century. Melville''s work predates the better-known municipal gas-lighting systems that followed elsewhere in the United States. The small marker is easy to miss on Pelham Street.', 'open', 'https://www.atlasobscura.com/places/location-of-the-first-gas-street-lamp', null, 'America/New_York', now()),
  ('General Nathanael Greene Homestead', 'general-nathanael-greene-homestead', 'haunted', 41.69389, -71.54413, 'Coventry', 'RI', 'The 1770 homestead of Revolutionary War General Nathanael Greene preserves period rooms and artifacts connected to one of Rhode Island''s most important military figures. Visitors and paranormal groups have also reported footsteps, voices and other unexplained experiences in and around the house, though these remain folklore rather than verified phenomena. Tours operate on a limited schedule.', 'limited', 'https://www.rimonthly.com/haunted-places-rhode-island/', 'https://nathanaelgreenehomestead.org/', 'America/New_York', now()),
  ('Governor William Sprague Mansion', 'governor-william-sprague-mansion', 'haunted', 41.79075, -71.45635, 'Cranston', 'RI', 'This nineteenth-century mansion was home to industrialist and Civil War-era Rhode Island governor William Sprague. Its long history, family tragedies and preserved interiors have produced decades of local ghost stories and reported paranormal encounters. The Cranston Historical Society opens the property for tours and special events rather than daily visitation.', 'limited', 'https://www.cranstonhistory.org/', 'https://www.cranstonhistory.org/', 'America/New_York', now()),
  ('Hamilton Hoppin House', 'hamilton-hoppin-house', 'haunted', 41.50643, -71.29752, 'Middletown', 'RI', 'This Gothic Revival mansion, later known through its use as an inn, has been associated with stories of apparitions and unexplained activity. Its architecture alone gives the property a distinctly haunted-house silhouette, complete with steep gables and elaborate nineteenth-century detailing. It currently operates as lodging, so access should be limited to guests or authorized visits.', 'limited', 'https://www.pbs.org/video/3-inn-shadow-lawn-uppfjm/', 'https://www.thehamiltonhoppinhouse.com/', 'America/New_York', now()),
  ('Former Ladd School Site', 'former-ladd-school-site', 'weird-history', 41.55222, -71.5431, 'Exeter', 'RI', 'The Joseph Ladd School was a state institution for people with intellectual and developmental disabilities and became notorious for overcrowding, abuse, segregation and Rhode Island''s eugenics-era policies. Most of the campus was demolished after the institution closed, and later ghost stories attached themselves to the abandoned buildings. OddWay should treat this primarily as institutional dark history; remaining structures are not an invitation to trespass.', 'roadside', 'https://www.theladdschool.com/history/', null, 'America/New_York', now()),
  ('Roger Williams Grave at Prospect Terrace', 'roger-williams-grave-at-prospect-terrace', 'weird-history', 41.82982, -71.407, 'Providence', 'RI', 'Roger Williams and his wife Mary were reinterred beneath the large monument at Prospect Terrace in 1939. Their earlier burial became famous because an apple-tree root grew through the grave in a human-like shape, the same root preserved by the Rhode Island Historical Society. This stop completes that story at Williams''s present resting place.', 'open', 'https://www.nps.gov/places/prospect-terrace.htm', null, 'America/New_York', now()),
  ('Sarah Helen Whitman House', 'sarah-helen-whitman-house', 'weird-history', 41.83106, -71.40923, 'Providence', 'RI', 'Poet Sarah Helen Whitman lived at 88 Benefit Street and became briefly engaged to Edgar Allan Poe in 1848. Their intense and unsuccessful courtship is one of Providence''s strongest direct links to Poe. The building is a private residence, so it should be viewed only from the public sidewalk. Secondary source: https://edgarallanpoeri.com/contact/', 'roadside', 'https://literaryprovidence.com/authors', null, 'America/New_York', now()),
  ('Gettysburg Gun — Rhode Island State House', 'gettysburg-gun-rhode-island-state-house', 'weird-history', 41.83083, -71.415, 'Providence', 'RI', 'Inside the Rhode Island State House is a bronze Napoleon cannon disabled during the artillery barrage preceding Pickett''s Charge at Gettysburg. A Confederate projectile lodged in the muzzle, permanently freezing the weapon in the instant it was knocked out of battle. Visitors must follow current State House public-access and security procedures.', 'limited', 'https://en.wikipedia.org/wiki/Rhode_Island_State_House', null, 'America/New_York', now()),
  ('John Rogers Vinton Cannonball Grave', 'john-rogers-vinton-cannonball-grave', 'weird-history', 41.85257, -71.38294, 'Providence', 'RI', 'Army officer John Rogers Vinton was killed during the Mexican-American War, and his Swan Point Cemetery monument incorporates a cannonball into the memorial. The unusual detail has made the grave one of the cemetery''s most memorable military monuments. The coordinate routes to Swan Point; ask cemetery staff for current directions to the Vinton monument and follow photography rules. Secondary source: https://www.roadsideamerica.com/tip/61358', 'limited', 'https://swanpointcemetery.com/the-estate/art-and-architecture/', null, 'America/New_York', now()),
  ('The Milk Can Building', 'the-milk-can-building', 'roadside-oddities', 41.96267, -71.4955, 'North Smithfield', 'RI', 'Built in the late 1920s, this giant milk-can-shaped structure once sold dairy products and ice cream beside Route 146. The building was later moved and has spent decades unused, but its oversized novelty architecture still makes it unmistakable from the highway corridor. It is private property and should be viewed only from a safe public location.', 'roadside', 'https://www.roadsideamerica.com/tip/8599', null, 'America/New_York', now()),
  ('Fort Mansfield Ruins', 'fort-mansfield-ruins', 'weird-history', 41.30639, -71.88361, 'Westerly', 'RI', 'Concrete remnants of Fort Mansfield survive in the dunes of Napatree Point, reached by a long coastal walk from Watch Hill. The Endicott-era fort operated in the early twentieth century before flaws in its defensive design helped make it obsolete. The surrounding conservation area is public, but seasonal wildlife restrictions and fragile dunes must be respected.', 'limited', 'https://fergusonmuseum.org/2020/06/fort-mansfield-napatree-point/', null, 'America/New_York', now()),
  ('Grave of Marie Rose Ferron', 'grave-of-marie-rose-ferron', 'folklore', 42.01708, -71.50365, 'Woonsocket', 'RI', 'Marie "Little Rose" Ferron was a Franco-American Catholic mystic whose followers reported stigmata, visions and extraordinary religious experiences during her life. Her grave in Precious Blood Cemetery remains a devotional destination, and the foundation dedicated to her records continuing reports of favors and cures attributed to her intercession. These are matters of religious belief rather than verified medical claims.', 'limited', 'https://www.littleroseferron.org/grave-site/', null, 'America/New_York', now()),
  ('Rose Ferron Foundation Museum & Domestic Chapel', 'rose-ferron-foundation-museum-domestic-chapel', 'museums', 42.00693, -71.5118, 'Woonsocket', 'RI', 'The Rose Ferron Foundation preserves personal objects, devotional material and portions of an elaborate handmade Domestic Chapel connected to Marie "Little Rose" Ferron. The organization occupies a castle-like former commercial building at 339 Arnold Street and continues restoring the museum complex. Check ahead because renovation can affect what is open to visitors.', 'limited', 'https://roseferronfri.org/new-location', 'https://roseferronfri.org/', 'America/New_York', now()),
  ('Electromagnetic Pinball Museum and Restoration', 'electromagnetic-pinball-museum-and-restoration', 'museums', 41.86799, -71.3992, 'Pawtucket', 'RI', 'This hands-on museum packs a large rotating collection of vintage and modern pinball machines, electromechanical games and classic arcade cabinets into a former industrial building. Admission currently covers unlimited free play rather than individual tokens or quarters. It is both a museum and a functioning preservation workshop for old amusement technology.', 'open', 'https://www.electromagneticpinballmuseum.com/', 'https://www.electromagneticpinballmuseum.com/', 'America/New_York', now()),
  ('Hachiko Statue at Woonsocket Depot', 'hachiko-statue-at-woonsocket-depot', 'weird-history', 42.00355, -71.5133, 'Woonsocket', 'RI', 'A bronze statue of the famously loyal Japanese dog Hachiko stands outside Woonsocket''s former train depot. The location was used while filming the 2009 movie "Hachi: A Dog''s Tale," with the Rhode Island city standing in for the film''s New England setting. The statue gives the movie connection a permanent physical marker.', 'open', 'https://www.roadsideamerica.com/tip/33728', null, 'America/New_York', now()),
  ('Flying Horse Carousel', 'flying-horse-carousel', 'roadside-oddities', 41.30912, -71.85814, 'Watch Hill', 'RI', 'This nineteenth-century carousel uses horses suspended from chains instead of the up-and-down poles found on most carousels. As the ride spins, centrifugal force sends the wooden horses outward, creating the impression that they are flying. It is one of the oldest continuously operating carousels of its type and runs seasonally.', 'limited', 'https://www.atlasobscura.com/places/flying-horse-carousel', null, 'America/New_York', now()),
  ('Purgatory Chasm', 'purgatory-chasm-middletown', 'roadside-oddities', 41.48733, -71.2694, 'Middletown', 'RI', 'A narrow coastal gorge cuts roughly 50 feet down through the rock at this small public overlook. Its dramatic name and sudden drop have inspired local stories while the actual formation offers a striking example of erosion along Aquidneck Island''s shoreline. Stay behind barriers and follow seasonal town access rules.', 'limited', 'https://www.middletownri.gov/Facilities/Facility/Details/Purgatory-Chasm-34', null, 'America/New_York', now()),
  ('Coffin and Mummy of Nesmin — RISD Museum', 'coffin-and-mummy-of-nesmin-risd-museum', 'museums', 41.82675, -71.40855, 'Providence', 'RI', 'RISD Museum preserves the coffin and mummified remains of Nesmin, an Egyptian priest who lived during the Ptolemaic period. The elaborately decorated coffin and surviving mummy make this one of Rhode Island''s most unusual museum objects. The museum currently lists the object as on view, but gallery rotations and hours should be checked before visiting.', 'limited', 'https://risdmuseum.org/art-design/collection/coffin-and-mummy-nesmin-38206', 'https://risdmuseum.org/', 'America/New_York', now()),
  ('Rocky Point Water-Tank Ruins', 'rocky-point-water-tank-ruins', 'weird-history', 41.6892, -71.36636, 'Warwick', 'RI', 'Rocky Point State Park preserves scattered remnants of the amusement park that operated here for generations before closing in the 1990s. Among the most evocative remains are concrete ruins associated with the old water-tank structure, separate from the World''s Fair arch included in Rhode Island Part 1. The ruins sit within the public state park and should be viewed without climbing unstable remnants.', 'open', 'https://riparks.ri.gov/parks/rocky-point-state-park', null, 'America/New_York', now()),
  ('Cranston Street Armory', 'cranston-street-armory', 'roadside-oddities', 41.81259, -71.43054, 'Providence', 'RI', 'Completed in 1907, the massive Cranston Street Armory resembles a medieval fortress planted in a Providence neighborhood, with twin towers and an enormous drill hall. Its scale and castle-like exterior have made it a favorite landmark even when the interior is not open. Unless an official event or tour is scheduled, treat this as an exterior viewing stop. Secondary source: https://www.atlasobscura.com/places/cranston-street-armory', 'roadside', 'https://www.goprovidence.com/listing/cranston-street-armory/24202/', null, 'America/New_York', now()),
  ('Living Sharks Museum', 'living-sharks-museum', 'museums', 41.3788, -71.82991, 'Westerly', 'RI', 'Living Sharks Museum calls itself America''s first shark-history museum and uses fossils, biological material, historic artifacts and pop-culture objects to tell the story of sharks and their conservation. Its collection also includes substantial material connected to "Jaws." Admission is free, and the museum currently lists a Memorial Day through Labor Day public season.', 'limited', 'https://www.livingsharks.org/visit', 'https://www.livingsharks.org/', 'America/New_York', now()),
  ('Green Jacket Shoal Ship Graveyard Viewpoint', 'green-jacket-shoal-ship-graveyard-viewpoint', 'weird-history', 41.81579, -71.3917, 'East Providence', 'RI', 'Just offshore from Providence and East Providence lies Green Jacket Shoal, an underwater graveyard containing the remains of abandoned nineteenth- and twentieth-century vessels along with debris from the waterfront''s industrial past. The wrecks are most apparent at low tide and are the subject of ongoing maritime archaeology. Route visitors to the public waterfront at Bold Point Park rather than onto the shoal or wreckage.', 'open', 'https://www.crmc.ri.gov/newsandevents/2018/20180516-shipgraveyard.html', 'https://eastprovidenceri.gov/facilities/park/bold-point-park', 'America/New_York', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as ri_stops from public.stops where state = 'RI';
